CREATE TYPE "Role" AS ENUM ('ADMIN', 'LDM', 'TEACHER');
CREATE TYPE "Phase" AS ENUM ('DIAGNOSTIC', 'SUMMATIVE');
CREATE TYPE "Domain" AS ENUM ('ACADEMIC', 'NUMERACY', 'READING');
CREATE TYPE "WorkStatus" AS ENUM ('DRAFT', 'QUEUED', 'PROCESSING', 'NEEDS_REVIEW', 'COMPLETED', 'FAILED', 'APPROVED');
CREATE TYPE "SyncStatus" AS ENUM ('PENDING', 'SYNCED', 'FAILED');

CREATE TABLE "User" ("id" TEXT PRIMARY KEY, "firstName" TEXT NOT NULL, "lastName" TEXT NOT NULL, "email" TEXT NOT NULL UNIQUE, "passwordHash" TEXT NOT NULL, "role" "Role" NOT NULL, "active" BOOLEAN NOT NULL DEFAULT true, "mustResetPassword" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Cohort" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL UNIQUE, "active" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "TeacherProfile" ("id" TEXT PRIMARY KEY, "userId" TEXT NOT NULL UNIQUE, "cohortId" TEXT NOT NULL, "ldmId" TEXT NOT NULL, "subject" TEXT NOT NULL, "grade" TEXT NOT NULL, CONSTRAINT "TeacherProfile_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE, CONSTRAINT "TeacherProfile_cohortId_fkey" FOREIGN KEY ("cohortId") REFERENCES "Cohort"("id"), CONSTRAINT "TeacherProfile_ldmId_fkey" FOREIGN KEY ("ldmId") REFERENCES "User"("id"));
CREATE TABLE "AssessmentTemplate" ("id" TEXT PRIMARY KEY, "title" TEXT NOT NULL, "phase" "Phase" NOT NULL, "domain" "Domain" NOT NULL, "subject" TEXT NOT NULL, "grade" TEXT NOT NULL, "answerKeyDriveUrl" TEXT NOT NULL, "answerKeyDriveFileId" TEXT NOT NULL, "rubricDriveUrl" TEXT, "rubricDriveFileId" TEXT, "instructions" TEXT, "maxScore" DOUBLE PRECISION NOT NULL, "active" BOOLEAN NOT NULL DEFAULT true, "promptVersion" TEXT NOT NULL DEFAULT 'v1', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "TeacherAnalysisSheet" ("id" TEXT PRIMARY KEY, "teacherId" TEXT NOT NULL UNIQUE, "sheetUrl" TEXT NOT NULL, "spreadsheetId" TEXT NOT NULL, "connectedById" TEXT NOT NULL, "connectedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "TeacherAnalysisSheet_teacherId_fkey" FOREIGN KEY ("teacherId") REFERENCES "TeacherProfile"("id") ON DELETE CASCADE, CONSTRAINT "TeacherAnalysisSheet_connectedById_fkey" FOREIGN KEY ("connectedById") REFERENCES "User"("id"));
CREATE TABLE "Submission" ("id" TEXT PRIMARY KEY, "teacherId" TEXT NOT NULL, "assessmentTemplateId" TEXT NOT NULL, "phase" "Phase" NOT NULL, "domain" "Domain" NOT NULL, "status" "WorkStatus" NOT NULL DEFAULT 'DRAFT', "idempotencyKey" TEXT NOT NULL UNIQUE, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Submission_teacherId_fkey" FOREIGN KEY ("teacherId") REFERENCES "TeacherProfile"("id"), CONSTRAINT "Submission_assessmentTemplateId_fkey" FOREIGN KEY ("assessmentTemplateId") REFERENCES "AssessmentTemplate"("id"));
CREATE TABLE "StudentWork" ("id" TEXT PRIMARY KEY, "submissionId" TEXT NOT NULL, "driveUrl" TEXT NOT NULL, "driveFileId" TEXT NOT NULL, "fileName" TEXT, "studentName" TEXT, "status" "WorkStatus" NOT NULL DEFAULT 'QUEUED', "score" DOUBLE PRECISION, "maxScore" DOUBLE PRECISION, "percentage" DOUBLE PRECISION, "overallConfidence" DOUBLE PRECISION, "aiResult" JSONB, "syncStatus" "SyncStatus" NOT NULL DEFAULT 'PENDING', "syncError" TEXT, "analyzedAt" TIMESTAMP(3), "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "StudentWork_submissionId_fkey" FOREIGN KEY ("submissionId") REFERENCES "Submission"("id") ON DELETE CASCADE, UNIQUE("submissionId", "driveFileId"));
CREATE TABLE "QuestionAnalysis" ("id" TEXT PRIMARY KEY, "studentWorkId" TEXT NOT NULL, "questionNumber" TEXT NOT NULL, "studentAnswer" TEXT, "teacherCorrectionDetected" BOOLEAN NOT NULL, "teacherCorrection" TEXT, "expectedAnswer" TEXT, "isCorrect" BOOLEAN NOT NULL, "scoreAwarded" DOUBLE PRECISION NOT NULL, "maxScore" DOUBLE PRECISION NOT NULL, "confidence" DOUBLE PRECISION NOT NULL, "reviewRequired" BOOLEAN NOT NULL, "reason" TEXT, CONSTRAINT "QuestionAnalysis_studentWorkId_fkey" FOREIGN KEY ("studentWorkId") REFERENCES "StudentWork"("id") ON DELETE CASCADE);
CREATE TABLE "HumanReview" ("id" TEXT PRIMARY KEY, "studentWorkId" TEXT NOT NULL, "questionAnalysisId" TEXT, "originalValue" JSONB NOT NULL, "correctedValue" JSONB NOT NULL, "correctedById" TEXT NOT NULL, "correctedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "resolved" BOOLEAN NOT NULL DEFAULT true, CONSTRAINT "HumanReview_studentWorkId_fkey" FOREIGN KEY ("studentWorkId") REFERENCES "StudentWork"("id"), CONSTRAINT "HumanReview_correctedById_fkey" FOREIGN KEY ("correctedById") REFERENCES "User"("id"));
CREATE TABLE "LdmComment" ("id" TEXT PRIMARY KEY, "studentWorkId" TEXT NOT NULL UNIQUE, "authorId" TEXT NOT NULL, "content" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "LdmComment_studentWorkId_fkey" FOREIGN KEY ("studentWorkId") REFERENCES "StudentWork"("id"), CONSTRAINT "LdmComment_authorId_fkey" FOREIGN KEY ("authorId") REFERENCES "User"("id"));
CREATE TABLE "Approval" ("id" TEXT PRIMARY KEY, "submissionId" TEXT NOT NULL UNIQUE, "teacherId" TEXT NOT NULL, "phase" "Phase" NOT NULL, "approvedById" TEXT NOT NULL, "approvedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "comments" TEXT, "finalMetrics" JSONB NOT NULL, CONSTRAINT "Approval_submissionId_fkey" FOREIGN KEY ("submissionId") REFERENCES "Submission"("id"), CONSTRAINT "Approval_approvedById_fkey" FOREIGN KEY ("approvedById") REFERENCES "User"("id"));
CREATE TABLE "GeneratedDocument" ("id" TEXT PRIMARY KEY, "approvalId" TEXT NOT NULL UNIQUE, "driveFileId" TEXT, "url" TEXT, "status" TEXT NOT NULL, "error" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "GeneratedDocument_approvalId_fkey" FOREIGN KEY ("approvalId") REFERENCES "Approval"("id"));
CREATE TABLE "GlobalResource" ("id" TEXT PRIMARY KEY, "title" TEXT NOT NULL, "description" TEXT, "url" TEXT NOT NULL, "targetRoles" "Role"[], "active" BOOLEAN NOT NULL DEFAULT true, "displayOrder" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "AuditLog" ("id" TEXT PRIMARY KEY, "actorUserId" TEXT, "action" TEXT NOT NULL, "entityType" TEXT NOT NULL, "entityId" TEXT, "metadata" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AuditLog_actorUserId_fkey" FOREIGN KEY ("actorUserId") REFERENCES "User"("id"));
CREATE TABLE "AppSetting" ("key" TEXT PRIMARY KEY, "value" JSONB NOT NULL, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "PasswordResetToken" ("id" TEXT PRIMARY KEY, "userId" TEXT NOT NULL, "tokenHash" TEXT NOT NULL UNIQUE, "expiresAt" TIMESTAMP(3) NOT NULL, "usedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "BackgroundJob" ("id" TEXT PRIMARY KEY, "type" TEXT NOT NULL, "entityId" TEXT NOT NULL, "status" TEXT NOT NULL, "attempts" INTEGER NOT NULL DEFAULT 0, "lastError" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, UNIQUE("type", "entityId"));
CREATE INDEX "Cohort_active_idx" ON "Cohort"("active"); CREATE INDEX "TeacherProfile_cohortId_idx" ON "TeacherProfile"("cohortId"); CREATE INDEX "TeacherProfile_ldmId_idx" ON "TeacherProfile"("ldmId");
CREATE UNIQUE INDEX "AssessmentTemplate_match_key" ON "AssessmentTemplate"("phase","domain","subject","grade","active"); CREATE INDEX "AssessmentTemplate_match_idx" ON "AssessmentTemplate"("active","phase","domain","subject","grade");
CREATE INDEX "Submission_teacherId_status_idx" ON "Submission"("teacherId","status"); CREATE INDEX "Submission_assessmentTemplateId_idx" ON "Submission"("assessmentTemplateId"); CREATE INDEX "StudentWork_submissionId_status_idx" ON "StudentWork"("submissionId","status"); CREATE INDEX "QuestionAnalysis_studentWorkId_idx" ON "QuestionAnalysis"("studentWorkId"); CREATE INDEX "HumanReview_studentWorkId_idx" ON "HumanReview"("studentWorkId"); CREATE INDEX "Approval_teacherId_phase_idx" ON "Approval"("teacherId","phase"); CREATE INDEX "AuditLog_actorUserId_createdAt_idx" ON "AuditLog"("actorUserId","createdAt"); CREATE INDEX "AuditLog_entityType_entityId_idx" ON "AuditLog"("entityType","entityId"); CREATE INDEX "PasswordResetToken_userId_idx" ON "PasswordResetToken"("userId"); CREATE INDEX "BackgroundJob_status_idx" ON "BackgroundJob"("status");
